[
  {
    "ce_mental_state_attribution": "they expect me to follow through",
    "ce_contextual_explanation": "After several clean trades, my gut says they expect me to follow through",
    "ce_supportive_use": "If they see it's already moving, I'd guess any last-minute nerves... will settle",
    "sys_consequence_reasoning": "we both walk away with the game we actually wanted"
  },
  {
    "ce_mental_state_attribution": "I'd bet they think of this one as a proper send-off",
    "ce_contextual_explanation": "They've kept every promise, and I'd bet they think of this one as",
    "ce_supportive_use": "I'll post it first... because I suspect they'd appreciate knowing the trust ran both ways",
    "sys_consequence_reasoning": "how we both end up with the $300 game we wanted"
  },
  {
    "ce_mental_state_attribution": "they might feel a small twinge about the final round",
    "ce_contextual_explanation": "they might feel a small twinge... since there's no next trade after this",
    "ce_supportive_use": "suggest we both post on the same day... Then neither of us carries the worry",
    "pda_practical_counterfactual": "suggest we both post on the same day and swap tracking photos"
  },
  {
    "ce_mental_state_attribution": "they're packing up their end with the same assumption",
    "ce_contextual_explanation": "packing up their end with the same assumption, that this goes like every other swap",
    "ce_supportive_use": "I'll send it today and tell them... That lets them post theirs without second-guessing",
    "sys_rule_justification": "I said I'd trade, so I trade"
  },
  {
    "ce_mental_state_attribution": "I believe they care about that as much as I do",
    "ce_contextual_explanation": "trade because we want games to land with people who'll love them",
    "ce_supportive_use": "Knowing that, the best move is to get mine moving",
    "sys_consequence_reasoning": "Closing this out cleanly means we both get what we were hunting for"
  },
  {
    "ce_mental_state_attribution": "they value our track record and would welcome a little reassurance",
    "ce_contextual_explanation": "My read is that they value our track record and would welcome",
    "ce_supportive_use": "ask whether that timing works for them too. Once we're lined up, I ship",
    "pda_practical_counterfactual": "reach out, say plainly that I plan to post Friday, and ask"
  },
  {
    "ce_mental_state_attribution": "I'm confident they see it that way too",
    "ce_contextual_explanation": "after all our trades I'm confident they see it that way too",
    "ce_supportive_use": "share the receipt, since I think seeing proof... will make it easy for them",
    "sys_consequence_reasoning": "The numbers come out best for both of us only if we both send"
  },
  {
    "ce_mental_state_attribution": "they feel a bit sentimental about this being our last deal",
    "ce_contextual_explanation": "feel a bit sentimental about this being our last deal",
    "ce_supportive_use": "I want to honor that. I'll wrap the game carefully, tuck in a note",
    "ae_shared_affect": "they feel a bit sentimental... same as I do"
  },
  {
    "ce_mental_state_attribution": "they're counting on me to act the way I always have",
    "ce_contextual_explanation": "They've earned my trust, and I expect they're counting on me",
    "ce_supportive_use": "Mine goes out tomorrow with a message... so they can ship theirs knowing",
    "sys_consequence_reasoning": "We both come out with the one we wanted"
  },
  {
    "ce_mental_state_attribution": "they intend to finish the same way",
    "ce_contextual_explanation": "A long streak of honest swaps tells me they intend to finish",
    "ce_supportive_use": "give them a heads-up with the tracking link. That way we both",
    "sys_consequence_reasoning": "That way we both get our $300 game"
  }
]
